INSERT INTO `oc_paperwork` (`zone_id`, `state`, `b2c_stat_levy_type`, `b2c_stat_levy_liable`, `b2c_paperwork_req`, `b2c_paperwork_exem_lim`, `b2b_paperwork_req`, `additional_notes`) VALUES
(1476, 'Andhra Pradesh', 'Nil', '', 'Shipper Invoice', 'Nil', 'CI + VAT Form x/600', 'Intra India movements of the commodities in exemption list of VAT & Entry Tax regulations of the destination state are not subject to any VAT form under B2C & B2B Movements. TIN number of shipper & Consignee on shipping invoice in case of B2B and of shipper in case of B2C is mandatory\nVAT Form wherever applicable may be for select goods or select category of dealers. Pls visit the destination state VAT website for further detail\nDeclaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement\nShipment to Arunachal Pradesh as gift or sample declared on Invoice upto the INR value 10,000 is allowed entry witilout Entry Tax. VAT form DG01 is filled up and signed by the carrier registered with VAT authority\nEnt Tax on B2C shipments to Odisha & WB is applicable for online/e-comm movements only, VAT form is applicable for other B2C, B2B & C2C movements\nShipments can move to Tripura (AAG )by air without VAT Form and will be delivered after endorsement of VAT form from VAT authority by the consignee\nEntry Tax is charged on selected commodity as listed under the destination state VAT website. Pls log on the respective state website or FedEx regulatory link before pickup under B2C movement\nMis-declaration may result in fine/ penalty / seizure of goods\nTransit pass is granted for Assam if the entry permits of the importing Statesare accompanied with shipments of NE regions.\nRegulatory requirement are same for surface and air mode unless specified otherwise in the destination state VAT regulations.\nIn most state VAT reaulations w.r.t. to e-commerce and personal shipments (B2C & C2C) are not clearly defined, therefore state boarder clearance is subject to the discretion of the concerned check post Vat officers.\nThreshold for Bihar& UP is under review by the respective VAT authorities. Threshold is suspended for these states until we have clear verdict from both the authorities. Status quo on exemption limit for B2B to Bihar & UP.\nThis document supersedes all documents posted or shared in past.'),
(1475, 'Andaman & Nicobar', 'Nil', '', 'Shipper Invoice', 'Nil', 'Shipper Invoice', 'Intra India movements of the commodities in exemption list of VAT & Entry Tax regulations of the destination state are not subject to any VAT form under B2C & B2B Movements. TIN number of shipper & Consignee on shipping invoice in case of B2B and of shipper in case of B2C is mandatory\r\nVAT Form wherever applicable may be for select goods or select category of dealers. Pls visit the destination state VAT website for further detail\r\nDeclaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement\r\nShipment to Arunachal Pradesh as gift or sample declared on Invoice upto the INR value 10,000 is allowed entry witilout Entry Tax. VAT form DG01 is filled up and signed by the carrier registered with VAT authority\r\nEnt Tax on B2C shipments to Odisha & WB is applicable for online/e-comm movements only, VAT form is applicable for other B2C, B2B & C2C movements\r\nShipments can move to Tripura (AAG )by air without VAT Form and will be delivered after endorsement of VAT form from VAT authority by the consignee\r\nEntry Tax is charged on selected commodity as listed under the destination state VAT website. Pls log on the respective state website or FedEx regulatory link before pickup under B2C movement\r\nMis-declaration may result in fine/ penalty / seizure of goods\r\nTransit pass is granted for Assam if the entry permits of the importing Statesare accompanied with shipments of NE regions.\r\nRegulatory requirement are same for surface and air mode unless specified otherwise in the destination state VAT regulations.\r\nIn most state VAT reaulations w.r.t. to e-commerce and personal shipments (B2C & C2C) are not clearly defined, therefore state boarder clearance is subject to the discretion of the concerned check post Vat officers.\r\nThreshold for Bihar& UP is under review by the respective VAT authorities. Threshold is suspended for these states until we have clear verdict from both the authorities. Status quo on exemption limit for B2B to Bihar & UP.\r\nThis document supersedes all documents posted or shared in past.'),
(1477, 'Arunachal Pradesh', 'Entry Tax', 'Consignee', 'CI + DG01 (TPT doc)', '<10,000', 'CI + RC of consignee**', 'Intra India movements of the commodities in exemption list of VAT & Entry Tax regulations of the destination state are not subject to any VAT form under B2C & B2B Movements. TIN number of shipper & Consignee on shipping invoice in case of B2B and of shipper in case of B2C is mandatory\n** Self certified copy of Registration certificate of consignee is required to move the shipment to Arunachal Pradesh\nVAT Form wherever applicable may be for select goods or select category of dealers. Pls visit the destination state VAT website for further detail\nDeclaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement\nShipment to Arunachal Pradesh as gift or sample declared on Invoice upto the INR value 10,000 is allowed entry witilout Entry Tax. VAT form DG01 is filled up and signed by the carrier registered with VAT authority\nEnt Tax on B2C shipments to Odisha & WB is applicable for online/e-comm movements only, VAT form is applicable for other B2C, B2B & C2C movements\nShipments can move to Tripura (AAG )by air without VAT Form and will be delivered after endorsement of VAT form from VAT authority by the consignee\nEntry Tax is charged on selected commodity as listed under the destination state VAT website. Pls log on the respective state website or FedEx regulatory link before pickup under B2C movement\nMis-declaration may result in fine/ penalty / seizure of goods\nTransit pass is granted for Assam if the entry permits of the importing Statesare accompanied with shipments of NE regions.\nRegulatory requirement are same for surface and air mode unless specified otherwise in the destination state VAT regulations.\nIn most state VAT reaulations w.r.t. to e-commerce and personal shipments (B2C & C2C) are not clearly defined, therefore state boarder clearance is subject to the discretion of the concerned check post Vat officers.\nThreshold for Bihar& UP is under review by the respective VAT authorities. Threshold is suspended for these states until we have clear verdict from both the authorities. Status quo on exemption limit for B2B to Bihar & UP.\nThis document supersedes all documents posted or shared in past.\n\n\n\n\nIntra India movements of the commodities in exemption list of VAT & Entry Tax regulations of the destination state are not subject to any VAT form under B2C & B2B Movements. TIN number of shipper & Consignee on shipping invoice in case of B2B and of shipper in case of B2C is mandatory\n** Self certified copy of Registration certificate of consignee is required to move the shipment to Arunachal Pradesh\nVAT Form wherever applicable may be for select goods or select category of dealers. Pls visit the destination state VAT website for further detail\nDeclaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement\nShipment to Arunachal Pradesh as gift or sample declared on Invoice upto the INR value 10,000 is allowed entry witilout Entry Tax. VAT form DG01 is filled up and signed by the carrier registered with VAT authority\nEnt Tax on B2C shipments to Odisha & WB is applicable for online/e-comm movements only, VAT form is applicable for other B2C, B2B & C2C movements\nShipments can move to Tripura (AAG )by air without VAT Form and will be delivered after endorsement of VAT form from VAT authority by the consignee\nEntry Tax is charged on selected commodity as listed under the destination state VAT website. Pls log on the respective state website or FedEx regulatory link before pickup under B2C movement\nMis-declaration may result in fine/ penalty / seizure of goods\nTransit pass is granted for Assam if the entry permits of the importing Statesare accompanied with shipments of NE regions.\nRegulatory requirement are same for surface and air mode unless specified otherwise in the destination state VAT regulations.\nIn most state VAT reaulations w.r.t. to e-commerce and personal shipments (B2C & C2C) are not clearly defined, therefore state boarder clearance is subject to the discretion of the concerned check post Vat officers.\nThreshold for Bihar& UP is under review by the respective VAT authorities. Threshold is suspended for these states until we have clear verdict from both the authorities. Status quo on exemption limit for B2B to Bihar & UP.\nThis document supersedes all documents posted or shared in past.'),
(1478, 'Assam', 'Entry Tax*', 'Carrier*', 'Cl+Form 62', '<20,000', 'CI + VAT Form 61', 'Intra India movements of the commodities in exemption list of VAT & Entry Tax regulations of the destination state are not subject to any VAT form under B2C & B2B Movements. TIN number of shipper & Consignee on shipping invoice in case of B2B and of shipper in case of B2C is mandatory\n*Entry permit for ecomm to Odisha, WB & Assam is exempted subject to Entry Tax . E comm shippers should be profiled before startup. FedEx readiness for Odisha & Assam is under review.\nVAT Form wherever applicable may be for select goods or select category of dealers. Pls visit the destination state VAT website for further detail\nDeclaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement\nShipment to Arunachal Pradesh as gift or sample declared on Invoice upto the INR value 10,000 is allowed entry witilout Entry Tax. VAT form DG01 is filled up and signed by the carrier registered with VAT authority\nEnt Tax on B2C shipments to Odisha & WB is applicable for online/e-comm movements only, VAT form is applicable for other B2C, B2B & C2C movements\nShipments can move to Tripura (AAG )by air without VAT Form and will be delivered after endorsement of VAT form from VAT authority by the consignee\nEntry Tax is charged on selected commodity as listed under the destination state VAT website. Pls log on the respective state website or FedEx regulatory link before pickup under B2C movement\nMis-declaration may result in fine/ penalty / seizure of goods\nTransit pass is granted for Assam if the entry permits of the importing Statesare accompanied with shipments of NE regions.\nRegulatory requirement are same for surface and air mode unless specified otherwise in the destination state VAT regulations.\nIn most state VAT reaulations w.r.t. to e-commerce and personal shipments (B2C & C2C) are not clearly defined, therefore state boarder clearance is subject to the discretion of the concerned check post Vat officers.\nThreshold for Bihar& UP is under review by the respective VAT authorities. Threshold is suspended for these states until we have clear verdict from both the authorities. Status quo on exemption limit for B2B to Bihar & UP.\nThis document supersedes all documents posted or shared in past.'),
(1479, 'Bihar', 'Entry Tax', 'Consignee', 'Cl+ Form D IX - on line', 'Nil', 'CI + VAT Form D IX for > 1NR 10K', 'Intra India movements of the commodities in exemption list of VAT & Entry Tax regulations of the destination state are not subject to any VAT form under B2C & B2B Movements. TIN number of shipper & Consignee on shipping invoice in case of B2B and of shipper in case of B2C is mandatory\r\nVAT Form wherever applicable may be for select goods or select category of dealers. Pls visit the destination state VAT website for further detail\r\nDeclaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement\r\nShipment to Arunachal Pradesh as gift or sample declared on Invoice upto the INR value 10,000 is allowed entry witilout Entry Tax. VAT form DG01 is filled up and signed by the carrier registered with VAT authority\r\nEnt Tax on B2C shipments to Odisha & WB is applicable for online/e-comm movements only, VAT form is applicable for other B2C, B2B & C2C movements\r\nShipments can move to Tripura (AAG )by air without VAT Form and will be delivered after endorsement of VAT form from VAT authority by the consignee\r\nEntry Tax is charged on selected commodity as listed under the destination state VAT website. Pls log on the respective state website or FedEx regulatory link before pickup under B2C movement\r\nMis-declaration may result in fine/ penalty / seizure of goods\r\nTransit pass is granted for Assam if the entry permits of the importing Statesare accompanied with shipments of NE regions.\r\nRegulatory requirement are same for surface and air mode unless specified otherwise in the destination state VAT regulations.\r\nIn most state VAT reaulations w.r.t. to e-commerce and personal shipments (B2C & C2C) are not clearly defined, therefore state boarder clearance is subject to the discretion of the concerned check post Vat officers.\r\nThreshold for Bihar& UP is under review by the respective VAT authorities. Threshold is suspended for these states until we have clear verdict from both the authorities. Status quo on exemption limit for B2B to Bihar & UP.\r\nThis document supersedes all documents posted or shared in past.'),
